-- The account generation fences a create request that reaches the database after
-- another tab has acknowledged the prior create. Old two-argument callers fail closed.
CREATE FUNCTION idealab_private.mutate_project_guard_v1(p_command jsonb,p_command_id uuid,p_create_generation bigint) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''
AS $generation$
DECLARE v_actor uuid:=auth.uid(); v_current_generation bigint;
BEGIN
  IF p_command->>'kind' IS DISTINCT FROM 'create' THEN
    RETURN idealab_private.mutate_project_v1(p_command,p_command_id);
  END IF;
  IF v_actor IS NULL OR p_command_id IS NULL THEN RETURN jsonb_build_object('status','denied'); END IF;
  -- This same row serializes generation reads, creates, and acknowledgements.
  PERFORM 1 FROM public.users WHERE id=v_actor FOR UPDATE;
  IF NOT FOUND OR NOT idealab_private.lab_opening_member_ready_v1() THEN
    RETURN jsonb_build_object('status','denied');
  END IF;
  PERFORM 1 FROM idealab_private.project_commands_v1 c
    WHERE c.user_id=v_actor AND c.command_id=p_command_id;
  IF FOUND THEN RETURN idealab_private.mutate_project_v1(p_command,p_command_id); END IF;
  IF p_create_generation IS NULL OR p_create_generation<1 THEN
    RETURN jsonb_build_object('status','stale_create');
  END IF;
  INSERT INTO idealab_private.project_create_generations_v1(user_id,generation)
    VALUES(v_actor,1) ON CONFLICT(user_id) DO NOTHING;
  SELECT g.generation INTO STRICT v_current_generation FROM idealab_private.project_create_generations_v1 g
    WHERE g.user_id=v_actor FOR UPDATE;
  IF v_current_generation<>p_create_generation THEN RETURN jsonb_build_object('status','stale_create'); END IF;
  RETURN idealab_private.mutate_project_v1(p_command,p_command_id);
END;
$generation$;

CREATE OR REPLACE FUNCTION idealab_private.get_own_project_create_intent_v1() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=''
AS $intent$
DECLARE v_command uuid; v_payload jsonb; v_project uuid; v_payload_fields integer; v_generation bigint:=1;
BEGIN
  IF auth.uid() IS NULL OR NOT idealab_private.lab_opening_member_ready_v1() THEN
    RETURN jsonb_build_object('status','unavailable');
  END IF;
  SELECT g.generation INTO v_generation FROM idealab_private.project_create_generations_v1 g WHERE g.user_id=auth.uid();
  IF NOT FOUND THEN v_generation:=1; END IF;
  SELECT i.command_id INTO v_command
    FROM idealab_private.project_create_intents_v1 i WHERE i.user_id=auth.uid();
  IF NOT FOUND THEN RETURN jsonb_build_object('status','clear','generation',v_generation::text); END IF;

  SELECT c.request,p.id INTO v_payload,v_project
    FROM idealab_private.project_commands_v1 c
    LEFT JOIN public.projects p ON p.id=CASE
      WHEN c.result->>'project_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (c.result->>'project_id')::uuid ELSE NULL END
      AND p.created_by=auth.uid()
    WHERE c.user_id=auth.uid() AND c.command_id=v_command
      AND c.request->>'kind'='create' AND c.result->>'status'='saved'
      AND c.result->>'project_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  IF NOT FOUND OR jsonb_typeof(v_payload) IS DISTINCT FROM 'object'
    THEN RETURN jsonb_build_object('status','unresolved','command_id',v_command,'payload',NULL,'project_id',v_project,'generation',v_generation::text);
  END IF;
  SELECT count(*) INTO v_payload_fields FROM jsonb_object_keys(v_payload);
  IF v_payload_fields<>4
    OR jsonb_typeof(v_payload->'kind') IS DISTINCT FROM 'string' OR v_payload->>'kind' IS DISTINCT FROM 'create'
    OR jsonb_typeof(v_payload->'title') IS DISTINCT FROM 'string'
    OR jsonb_typeof(v_payload->'description') IS DISTINCT FROM 'string'
    OR jsonb_typeof(v_payload->'visibility') IS DISTINCT FROM 'string'
    OR length(v_payload->>'title') NOT BETWEEN 1 AND 160
    OR (v_payload->>'title') ~ '^[[:space:]]*$' OR (v_payload->>'title') ~ '[[:cntrl:]]'
    OR length(v_payload->>'description') NOT BETWEEN 1 AND 4000
    OR (v_payload->>'description') ~ '^[[:space:]]*$'
    OR regexp_replace(v_payload->>'description',E'[\t\n\r]','','g') ~ '[[:cntrl:]]'
    OR (v_payload->>'visibility') NOT IN ('public','private') THEN
    RETURN jsonb_build_object('status','unresolved','command_id',v_command,'payload',NULL,'project_id',v_project,'generation',v_generation::text);
  END IF;
  RETURN jsonb_build_object('status','unresolved','command_id',v_command,'payload',v_payload,'project_id',v_project,'generation',v_generation::text);
END;
$intent$;

CREATE OR REPLACE FUNCTION idealab_private.ack_own_project_create_v1(p_command_id uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''
AS $ack$
DECLARE v_actor uuid:=auth.uid(); v_current uuid; v_project_ref uuid; v_project uuid; v_owner uuid;
  v_request jsonb; v_deleted integer; v_request_fields integer; v_generation bigint; v_advanced integer;
BEGIN
  IF v_actor IS NULL OR p_command_id IS NULL OR NOT idealab_private.lab_opening_member_ready_v1() THEN
    RETURN jsonb_build_object('status','conflict');
  END IF;
  PERFORM 1 FROM public.users WHERE id=v_actor FOR UPDATE;
  IF NOT idealab_private.lab_opening_member_ready_v1() THEN RETURN jsonb_build_object('status','conflict'); END IF;
  SELECT command_id INTO v_current FROM idealab_private.project_create_intents_v1 WHERE user_id=v_actor;
  IF FOUND AND v_current<>p_command_id THEN RETURN jsonb_build_object('status','conflict'); END IF;

  SELECT c.request,(c.result->>'project_id')::uuid INTO v_request,v_project_ref
    FROM idealab_private.project_commands_v1 c
    WHERE c.user_id=v_actor AND c.command_id=p_command_id
      AND c.request->>'kind'='create' AND c.result->>'status'='saved'
      AND c.result->>'project_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  IF NOT FOUND THEN RETURN jsonb_build_object('status','conflict'); END IF;
  SELECT p.id,p.created_by INTO v_project,v_owner FROM public.projects p WHERE p.id=v_project_ref;
  IF FOUND AND v_owner IS DISTINCT FROM v_actor THEN RETURN jsonb_build_object('status','conflict'); END IF;
  IF v_project IS NULL THEN
    IF jsonb_typeof(v_request) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('status','conflict'); END IF;
    SELECT count(*) INTO v_request_fields FROM jsonb_object_keys(v_request);
    IF v_request_fields<>4 OR jsonb_typeof(v_request->'kind') IS DISTINCT FROM 'string'
      OR v_request->>'kind' IS DISTINCT FROM 'create' OR jsonb_typeof(v_request->'title') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_request->'description') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_request->'visibility') IS DISTINCT FROM 'string'
      OR length(v_request->>'title') NOT BETWEEN 1 AND 160 OR (v_request->>'title') ~ '^[[:space:]]*$'
      OR (v_request->>'title') ~ '[[:cntrl:]]' OR length(v_request->>'description') NOT BETWEEN 1 AND 4000
      OR (v_request->>'description') ~ '^[[:space:]]*$'
      OR regexp_replace(v_request->>'description',E'[\t\n\r]','','g') ~ '[[:cntrl:]]'
      OR (v_request->>'visibility') NOT IN ('private','public') THEN
      RETURN jsonb_build_object('status','conflict');
    END IF;
  END IF;

  IF v_current=p_command_id THEN
    INSERT INTO idealab_private.project_create_generations_v1(user_id,generation)
      VALUES(v_actor,1) ON CONFLICT(user_id) DO NOTHING;
    SELECT generation INTO STRICT v_generation FROM idealab_private.project_create_generations_v1
      WHERE user_id=v_actor FOR UPDATE;
    IF v_generation=9223372036854775807 THEN RETURN jsonb_build_object('status','conflict'); END IF;
    DELETE FROM idealab_private.project_create_intents_v1
      WHERE user_id=v_actor AND command_id=p_command_id;
    GET DIAGNOSTICS v_deleted=ROW_COUNT;
    IF v_deleted<>1 THEN RETURN jsonb_build_object('status','conflict'); END IF;
    UPDATE idealab_private.project_create_generations_v1 SET generation=v_generation+1
      WHERE user_id=v_actor AND generation=v_generation;
    GET DIAGNOSTICS v_advanced=ROW_COUNT;
    IF v_advanced<>1 THEN RAISE EXCEPTION 'project create generation update lost its account lock'; END IF;
  END IF;
  RETURN jsonb_build_object('status','acknowledged','project_id',v_project);
END;
$ack$;

