CREATE FUNCTION idealab_private.guard_project_create_command_v1() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''
AS $command_gate$
DECLARE v_token text:=pg_catalog.current_setting('idealab.project_create_generation',true);
  v_command text:=pg_catalog.current_setting('idealab.project_create_command',true);
  v_requested_generation bigint; v_current_generation bigint;
BEGIN
  IF NEW.request->>'kind' IS DISTINCT FROM 'create' THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid()
    OR v_command IS DISTINCT FROM NEW.command_id::text
    OR v_token IS NULL OR v_token !~ '^[1-9][0-9]{0,18}$'
    OR (length(v_token)=19 AND v_token COLLATE "C">'9223372036854775807' COLLATE "C") THEN
    RAISE EXCEPTION 'project create requires the current guarded command generation'
      USING ERRCODE='23514';
  END IF;
  v_requested_generation:=v_token::bigint;
  SELECT g.generation INTO v_current_generation FROM idealab_private.project_create_generations_v1 g
    WHERE g.user_id=NEW.user_id FOR UPDATE;
  IF NOT FOUND OR v_current_generation<>v_requested_generation THEN
    RAISE EXCEPTION 'project create generation is stale'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$command_gate$;

CREATE FUNCTION idealab_private.advance_project_create_generation_v1() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''
AS $intent_gate$
DECLARE v_current_generation bigint; v_next_generation bigint; v_advanced integer;
BEGIN
  -- Account deletion cascades intent rows too; let the generation FK cascade.
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id=OLD.user_id) THEN RETURN OLD; END IF;
  IF OLD.create_generation=9223372036854775807 THEN
    RAISE EXCEPTION 'project create generation exhausted' USING ERRCODE='23514';
  END IF;
  v_next_generation:=OLD.create_generation+1;
  -- A pre-generation account may not have a row yet. Missing rows are valid only
  -- for historical epoch-1 receipts; a later epoch must never be reconstructed.
  IF OLD.create_generation<>1 THEN
    PERFORM 1 FROM idealab_private.project_create_generations_v1 g WHERE g.user_id=OLD.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'project create generation is missing' USING ERRCODE='23514'; END IF;
  END IF;
  INSERT INTO idealab_private.project_create_generations_v1(user_id,generation)
    VALUES(OLD.user_id,2) ON CONFLICT(user_id) DO NOTHING;
  SELECT g.generation INTO STRICT v_current_generation FROM idealab_private.project_create_generations_v1 g
    WHERE g.user_id=OLD.user_id FOR UPDATE;
  -- The current ack body lets this deferred trigger advance. An older generation-
  -- aware body may already have done the same update before the trigger fires.
  IF v_current_generation=OLD.create_generation THEN
    UPDATE idealab_private.project_create_generations_v1 SET generation=v_next_generation
      WHERE user_id=OLD.user_id AND generation=OLD.create_generation;
    GET DIAGNOSTICS v_advanced=ROW_COUNT;
    IF v_advanced<>1 THEN RAISE EXCEPTION 'project create generation update lost its account lock'; END IF;
  ELSIF v_current_generation<>v_next_generation THEN
    RAISE EXCEPTION 'project create generation changed unexpectedly' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
END;
$intent_gate$;

CREATE FUNCTION idealab_private.stamp_project_create_generation_v1() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''
AS $intent_stamp$
DECLARE v_actor uuid:=auth.uid(); v_command text:=pg_catalog.current_setting('idealab.project_create_command',true);
  v_token text:=pg_catalog.current_setting('idealab.project_create_generation',true);
