  IF v_actor IS NULL OR NEW.user_id IS DISTINCT FROM v_actor OR v_command IS DISTINCT FROM NEW.command_id::text
    OR v_token IS NULL OR v_token !~ '^[1-9][0-9]{0,18}$'
