    RAISE EXCEPTION 'project create intent requires the current guarded command generation' USING ERRCODE='23514';
  END IF;
  v_requested_generation:=v_token::bigint;
  SELECT g.generation INTO v_current_generation FROM idealab_private.project_create_generations_v1 g
    WHERE g.user_id=NEW.user_id FOR UPDATE;
